// Pine Script v5 code for Structural Pivots Method (SPM) with Buy/Sell Signals
//@version=5
indicator("Structural Pivots Method (SPM)", overlay=true)

// === Small Pivot Tracking Variables ===
var int sp_anchor_index = na
var float sp_anchor_high = na
var float sp_anchor_low = na
var bool looking_for_sph = true
var bool looking_for_spl = false
var int sph_count = 0
var int spl_count = 0
var float sph_high_candidate = na
var float spl_low_candidate = na

// Initialize on first bar
if bar_index == 0
    sp_anchor_index := bar_index
    sp_anchor_high := high
    sp_anchor_low := low
    sph_high_candidate := high
    spl_low_candidate := low

// Track current SPH/SPL values
var float temp_small_pivot_high = na
var float perm_small_pivot_high = na
var float temp_small_pivot_low = na
var float perm_small_pivot_low = na
var int last_sph_index = na
var int last_spl_index = na

// === SPH Detection Logic ===
if looking_for_sph and !na(sp_anchor_high)
    // Update highest high candidate
    if high > sph_high_candidate
        sph_high_candidate := high

    // Count qualifying bars (lower high and lower close vs anchor)
    if high < sp_anchor_high and close < sp_anchor_low
        sph_count += 1

    // Confirm SPH when two qualifying bars found (non-consecutive allowed)
    if sph_count >= 2
        // Mark as temporary SPH
        temp_small_pivot_high := sph_high_candidate
        last_sph_index := bar_index

        // Reset for next pivot type (SPL)
        looking_for_sph := false
        looking_for_spl := true
        sp_anchor_index := bar_index
        sp_anchor_high := high
        sp_anchor_low := low
        sph_count := 0
        sph_high_candidate := na

// === SPL Detection Logic ===
if looking_for_spl and !na(sp_anchor_low)
    // Update lowest low candidate
    if low < spl_low_candidate
        spl_low_candidate := low

    // Count qualifying bars (higher high and higher close vs anchor)
    if high > sp_anchor_high and close > sp_anchor_low
        spl_count += 1

    // Confirm SPL when two qualifying bars found (non-consecutive allowed)
    if spl_count >= 2
        // Mark as temporary SPL
        temp_small_pivot_low := spl_low_candidate
        last_spl_index := bar_index

        // Reset for next pivot type (SPH)
        looking_for_sph := true
        looking_for_spl := false
        sp_anchor_index := bar_index
        sp_anchor_high := high
        sp_anchor_low := low
        spl_count := 0
        spl_low_candidate := na

// === Convert temporary pivots to permanent when next pivot is confirmed ===
if !na(temp_small_pivot_high) and !na(perm_small_pivot_low)
    perm_small_pivot_high := temp_small_pivot_high
    temp_small_pivot_high := na
else if !na(temp_small_pivot_high) and bar_index > 100 and na(perm_small_pivot_high)
    // If no pivot confirmed after many bars, reset
    temp_small_pivot_high := na
    looking_for_sph := true
    looking_for_spl := false

if !na(temp_small_pivot_low) and !na(perm_small_pivot_high)
    perm_small_pivot_low := temp_small_pivot_low
    temp_small_pivot_low := na
else if !na(temp_small_pivot_low) and bar_index > 100 and na(perm_small_pivot_low)
    // If no pivot confirmed after many bars, reset
    temp_small_pivot_low := na
    looking_for_sph := false
    looking_for_spl := true

// Store confirmed SPH/SPL in arrays
var array<float> sph_array = array.new_float()
var array<int> sph_index_array = array.new_int()
var array<float> spl_array = array.new_float()
var array<int> spl_index_array = array.new_int()

if !na(perm_small_pivot_high)
    array.push(sph_array, perm_small_pivot_high)
    array.push(sph_index_array, last_sph_index)

if !na(perm_small_pivot_low)
    array.push(spl_array, perm_small_pivot_low)
    array.push(spl_index_array, last_spl_index)

// === Large Pivot Detection ===
var array<float> lph_array = array.new_float()
var array<int> lph_index_array = array.new_int()
var array<float> lpl_array = array.new_float()
var array<int> lpl_index_array = array.new_int()

// Check for LPH (Large Pivot High) when breaking SPL
if !na(perm_small_pivot_low)
    if high > perm_small_pivot_low
        float new_lph = na
        int new_lph_index = na

        if array.size(sph_array) > 0
            // Find highest SPH since last LPL
            int last_lpl_index = array.size(lpl_index_array) > 0 ? array.get(lpl_index_array, array.size(lpl_index_array)-1) : na

            for i = array.size(sph_array)-1 to 0 by -1
                sph_idx = array.get(sph_index_array, i)
                if na(last_lpl_index) or sph_idx > last_lpl_index
                    sph_val = array.get(sph_array, i)
                    if na(new_lph) or sph_val > new_lph
                        new_lph := sph_val
                        new_lph_index := sph_idx

            if !na(new_lph)
                array.push(lph_array, new_lph)
                array.push(lph_index_array, new_lph_index)

// Check for LPL (Large Pivot Low) when breaking SPH
if !na(perm_small_pivot_high)
    if low < perm_small_pivot_high
        float new_lpl = na
        int new_lpl_index = na

        if array.size(spl_array) > 0
            // Find lowest SPL since last LPH
            int last_lph_index = array.size(lph_index_array) > 0 ? array.get(lph_index_array, array.size(lph_index_array)-1) : na

            for i = array.size(spl_array)-1 to 0 by -1
                spl_idx = array.get(spl_index_array, i)
                if na(last_lph_index) or spl_idx > last_lph_index
                    spl_val = array.get(spl_array, i)
                    if na(new_lpl) or spl_val < new_lpl
                        new_lpl := spl_val
                        new_lpl_index := spl_idx

            if !na(new_lpl)
                array.push(lpl_array, new_lpl)
                array.push(lpl_index_array, new_lpl_index)

// === Buy/Sell Signals ===
bool buy_signal = false
bool sell_signal = false

// Only generate signals after we have at least two of each large pivot
if array.size(lph_array) >= 2 and array.size(lpl_array) >= 2
    last_lph = array.get(lph_array, array.size(lph_array)-1)
    last_lpl = array.get(lpl_array, array.size(lpl_array)-1)
    prev_lph = array.get(lph_array, array.size(lph_array)-2)
    prev_lpl = array.get(lpl_array, array.size(lpl_array)-2)

    // Get indices to ensure proper alternation
    last_lph_idx = array.get(lph_index_array, array.size(lph_index_array)-1)
    last_lpl_idx = array.get(lpl_index_array, array.size(lpl_index_array)-1)

    // Ensure proper alternation of large pivots
    if (last_lph_idx > last_lpl_idx and last_lpl_idx > array.get(lpl_index_array, array.size(lpl_index_array)-2)) or 
       (last_lpl_idx > last_lph_idx and last_lph_idx > array.get(lph_index_array, array.size(lph_index_array)-2))
        // Buy when we have higher high and higher low in LPs
        if last_lph > prev_lph and last_lpl > prev_lpl
            buy_signal := true

        // Sell when we have lower high and lower low in LPs
        if last_lph < prev_lph and last_lpl < prev_lpl
            sell_signal := true

// Plot Signals
plotshape(buy_signal, title="Buy Signal", location=location.belowbar, color=color.green, style=shape.labelup, text="BUY")
plotshape(sell_signal, title="Sell Signal", location=location.abovebar, color=color.red, style=shape.labeldown, text="SELL")

// === Visual Elements ===
plot(temp_small_pivot_high, title="Temporary Small Pivot High", style=plot.style_circle, color=color.orange, linewidth=1)
plot(perm_small_pivot_high, title="Permanent Small Pivot High", style=plot.style_circle, color=color.red, linewidth=2)
plot(temp_small_pivot_low, title="Temporary Small Pivot Low", style=plot.style_circle, color=color.yellow, linewidth=1)
plot(perm_small_pivot_low, title="Permanent Small Pivot Low", style=plot.style_circle, color=color.green, linewidth=2)
plot(array.size(lph_array) > 0 ? array.get(lph_array, array.size(lph_array)-1) : na, title="Large Pivot High", style=plot.style_line, color=color.purple, linewidth=3)
plot(array.size(lpl_array) > 0 ? array.get(lpl_array, array.size(lpl_array)-1) : na, title="Large Pivot Low", style=plot.style_line, color=color.blue, linewidth=3)

