#include <iostream>
#include <vector>
#include <cuda_runtime.h>
#include <mpi.h>
#include <thrust/device_vector.h>
#include <thrust/sort.h>

// CUDA kernel for neuron integration
__global__ void integrate_neurons_kernel(float* v, float* u, const float* a, const float* b, 
                                        const float* threshold, const float* c, const float* d,
                                        const float* input, float dt, int num_neurons) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < num_neurons) {
        // Izhikevich neuron dynamics
        float dv = (0.04f * v[i] * v[i] + 5.0f * v[i] + 140.0f - u[i] + input[i]) * dt;
        v[i] += dv;

        float du = (a[i] * (b[i] * v[i] - u[i])) * dt;
        u[i] += du;
    }
}

// CUDA kernel for spike detection and reset
__global__ void detect_spikes_kernel(float* v, float* u, const float* threshold, 
                                    const float* c, const float* d, float* last_spike_time,
                                    bool* spike, float current_time, int num_neurons) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < num_neurons) {
        if (v[i] >= threshold[i]) {
            spike[i] = true;
            last_spike_time[i] = current_time;
            v[i] = c[i];
            u[i] += d[i];
        } else {
            spike[i] = false;
        }
    }
}

// CUDA kernel for STDP updates
__global__ void update_stdp_kernel(const bool* spike, const float* last_spike_time,
                                 float* weights, int* row_indices, int* col_indices,
                                 int num_connections, float tau_stdp, float min_weight, float max_weight) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < num_connections) {
        int pre_idx = row_indices[i];
        int post_idx = col_indices[i];

        if (spike[pre_idx] && !spike[post_idx]) {
            // Post-synaptic spike before pre-synaptic (LTD)
            float delta_t = last_spike_time[post_idx] - last_spike_time[pre_idx];
            if (delta_t < 0 && -delta_t < tau_stdp) {
                weights[i] = fmaxf(min_weight, weights[i] - 0.1f * weights[i]);
            }
        } else if (!spike[pre_idx] && spike[post_idx]) {
            // Pre-synaptic spike before post-synaptic (LTP)
            float delta_t = last_spike_time[post_idx] - last_spike_time[pre_idx];
            if (delta_t > 0 && delta_t < tau_stdp) {
                weights[i] = fminf(max_weight, weights[i] + 0.1f * (1.0f - weights[i]));
            }
        }
    }
}

// CUDA kernel for synaptic current calculation
__global__ void calculate_synaptic_currents_kernel(float* currents, const bool* spike, 
                                               const float* weights, int* row_indices, 
                                               int* col_indices, int num_connections) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < num_connections) {
        int pre_idx = row_indices[i];
        int post_idx = col_indices[i];

        // If presynaptic neuron spiked, contribute to postsynaptic current
        if (spike[pre_idx]) {
            // Simple current-based synapse model
            atomicAdd(&currents[post_idx], weights[i]);
        }
    }
}

class DistributedNeuralNetwork {
public:
    DistributedNeuralNetwork(int total_neurons, int local_neurons, float dt)
        : total_neurons_(total_neurons), local_neurons_(local_neurons), dt_(dt) {

        // Initialize MPI
        MPI_Comm_size(MPI_COMM_WORLD, &num_procs_);
        MPI_Comm_rank(MPI_COMM_WORLD, &rank_);

        // Calculate local neuron range
        neurons_per_proc_ = total_neurons / num_procs_;
        int remainder = total_neurons % num_procs_;
        if (rank_ < remainder) {
            local_neurons_start_ = rank_ * (neurons_per_proc_ + 1);
            local_neurons_end_ = local_neurons_start_ + neurons_per_proc_ + 1;
        } else {
            local_neurons_start_ = rank_ * neurons_per_proc_ + remainder;
            local_neurons_end_ = local_neurons_start_ + neurons_per_proc_;
        }

        local_neurons_ = local_neurons_end_ - local_neurons_start_;

        // Allocate device memory for neuron states
        cudaMalloc(&v_, local_neurons_ * sizeof(float));
        cudaMalloc(&u_, local_neurons_ * sizeof(float));
        cudaMalloc(&a_, local_neurons_ * sizeof(float));
        cudaMalloc(&b_, local_neurons_ * sizeof(float));
        cudaMalloc(&c_, local_neurons_ * sizeof(float));
        cudaMalloc(&d_, local_neurons_ * sizeof(float));
        cudaMalloc(&threshold_, local_neurons_ * sizeof(float));
        cudaMalloc(&last_spike_time_, local_neurons_ * sizeof(float));
        cudaMalloc(&spike_, local_neurons_ * sizeof(bool));
        cudaMalloc(&currents_, local_neurons_ * sizeof(float));

        // Initialize neuron states
        std::vector<float> h_v(local_neurons_, -70.0f);
        std::vector<float> h_u(local_neurons_, 0.0f);
        std::vector<float> h_last_spike_time(local_neurons_, -1.0f);

        cudaMemcpy(v_, h_v.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(u_, h_u.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(last_spike_time_, h_last_spike_time.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice);

        // Initialize neuron parameters (default values)
        std::vector<float> h_a(local_neurons_, 0.02f);
        std::vector<float> h_b(local_neurons_, 0.2f);
        std::vector<float> h_c(local_neurons_, -65.0f);
        std::vector<float> h_d(local_neurons_, 8.0f);
        std::vector<float> h_threshold(local_neurons_, 30.0f);

        cudaMemcpy(a_, h_a.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(b_, h_b.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(c_, h_c.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(d_, h_d.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(threshold_, h_threshold.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice);
    }

    ~DistributedNeuralNetwork() {
        // Free device memory
        cudaFree(v_);
        cudaFree(u_);
        cudaFree(a_);
        cudaFree(b_);
        cudaFree(c_);
        cudaFree(d_);
        cudaFree(threshold_);
        cudaFree(last_spike_time_);
        cudaFree(spike_);
        cudaFree(currents_);

        if (row_indices_) cudaFree(row_indices_);
        if (col_indices_) cudaFree(col_indices_);
        if (weights_) cudaFree(weights_);
    }

    void set_connectivity(int* row_indices, int* col_indices, float* weights, int num_connections) {
        // Store synaptic connections in CSR format on device
        num_connections_ = num_connections;
        cudaMalloc(&row_indices_, num_connections * sizeof(int));
        cudaMalloc(&col_indices_, num_connections * sizeof(int));
        cudaMalloc(&weights_, num_connections * sizeof(float));

        cudaMemcpy(row_indices_, row_indices, num_connections * sizeof(int), cudaMemcpyHostToDevice);
        cudaMemcpy(col_indices_, col_indices, num_connections * sizeof(int), cudaMemcpyHostToDevice);
        cudaMemcpy(weights_, weights, num_connections * sizeof(float), cudaMemcpyHostToDevice);
    }

    void set_neuron_params(int neuron_idx, float a, float b, float c, float d, float threshold) {
        if (neuron_idx >= local_neurons_start_ && neuron_idx < local_neurons_end_) {
            int local_idx = neuron_idx - local_neurons_start_;
            cudaMemcpy(&a_[local_idx], &a, sizeof(float), cudaMemcpyHostToDevice);
            cudaMemcpy(&b_[local_idx], &b, sizeof(float), cudaMemcpyHostToDevice);
            cudaMemcpy(&c_[local_idx], &c, sizeof(float), cudaMemcpyHostToDevice);
            cudaMemcpy(&d_[local_idx], &d, sizeof(float), cudaMemcpyHostToDevice);
            cudaMemcpy(&threshold_[local_idx], &threshold, sizeof(float), cudaMemcpyHostToDevice);
        }
    }

    void step() {
        // Zero out currents
        cudaMemset(currents_, 0, local_neurons_ * sizeof(float));

        // Calculate synaptic currents
        int blockSize = 256;
        int numBlocks = (num_connections_ + blockSize - 1) / blockSize;
        calculate_synaptic_currents_kernel<<<numBlocks, blockSize>>>(
            currents_, spike_, weights_, row_indices_, col_indices_, num_connections_);

        // Integrate neuron dynamics
        numBlocks = (local_neurons_ + blockSize - 1) / blockSize;
        integrate_neurons_kernel<<<numBlocks, blockSize>>>(
            v_, u_, a_, b_, threshold_, c_, d_, currents_, dt_, local_neurons_);

        // Detect spikes
        detect_spikes_kernel<<<numBlocks, blockSize>>>(
            v_, u_, threshold_, c_, d_, last_spike_time_, spike_, current_time_, local_neurons_);

        // Apply STDP updates
        numBlocks = (num_connections_ + blockSize - 1) / blockSize;
        update_stdp_kernel<<<numBlocks, blockSize>>>(
            spike_, last_spike_time_, weights_, row_indices_, col_indices_, 
            num_connections_, tau_stdp_, min_weight_, max_weight_);

        // Communicate spikes between MPI processes
        communicate_spikes();

        current_time_ += dt_;
    }

    void run_simulation(float duration) {
        int steps = static_cast<int>(duration / dt_);

        for (int i = 0; i < steps; ++i) {
            step();

            // Progress tracking
            if (i % (steps / 10) == 0 && rank_ == 0) {
                std::cout << "Simulation progress: " << (i * 100.0 / steps) << "% complete\r";
            }
        }
    }

    void disconnect_neurons(int pre_idx, int post_idx) {
        // Search for connection and set weight to 0
        for (int i = 0; i < num_connections_; ++i) {
            int pre, post;
            cudaMemcpy(&pre, &row_indices_[i], sizeof(int), cudaMemcpyDeviceToHost);
            cudaMemcpy(&post, &col_indices_[i], sizeof(int), cudaMemcpyDeviceToHost);
            if (pre == pre_idx && post == post_idx) {
                float zero = 0.0f;
                cudaMemcpy(&weights_[i], &zero, sizeof(float), cudaMemcpyHostToDevice);
                break;
            }
        }
    }

private:
    void communicate_spikes() {
        // Gather all spikes on root node
        std::vector<bool> global_spikes(total_neurons_, false);
        std::vector<bool> local_spikes(local_neurons_);

        // Copy local spikes from device to host
        cudaMemcpy(local_spikes.data(), spike_, local_neurons_ * sizeof(bool), cudaMemcpyDeviceToHost);

        // Gather all spikes (simplified for example)
        MPI_Allgather(local_spikes.data(), local_neurons_, MPI_CXX_BOOL,
                      global_spikes.data(), local_neurons_, MPI_CXX_BOOL, MPI_COMM_WORLD);

        // Update synaptic currents based on global spikes (would happen in next step)
    }

    // Neuron parameters
    int total_neurons_;
    int local_neurons_;
    float dt_;
    float current_time_ = 0.0f;
    float tau_stdp_ = 20.0f;
    float min_weight_ = 0.1f;
    float max_weight_ = 2.0f;

    // MPI parameters
    int num_procs_;
    int rank_;
    int neurons_per_proc_;
    int local_neurons_start_;
    int local_neurons_end_;

    // Device pointers
    float* v_;
    float* u_;
    float* a_;
    float* b_;
    float* c_;
    float* d_;
    float* threshold_;
    float* last_spike_time_;
    bool* spike_;
    float* currents_;

    // Connectivity data
    int num_connections_ = 0;
    int* row_indices_ = nullptr;
    int* col_indices_ = nullptr;
    float* weights_ = nullptr;
};

