    # Mean motion (radians per day)
    n = 2 * math.pi / planet['period']

    # Mean anomaly
    M = n * time_days

    # Solve Kepler's equation
    E = M
    for _ in range(100):  # Newton-Raphson method
        E = E - (E - planet['eccentricity'] * math.sin(E) - M) / (1 - planet['eccentricity'] * math.cos(E))

    # Calculate position in orbital plane
    x = planet['semi_major_axis'] * (math.cos(E) - planet['eccentricity'])
    y = planet['semi_major_axis'] * math.sqrt(1 - planet['eccentricity']**2) * math.sin(E)

    return (x, y)

def generate_simulation_data(timestamp=None):
    """
    Generate simulation data for current time
    Returns JSON-compatible structure
    """
    if timestamp is None:
        timestamp = datetime.now().timestamp()

    days_since_epoch = (timestamp - datetime(2023, 1, 1).timestamp()) / (24 * 3600)

    simulation_data = {
        'timestamp': timestamp,
        'planets': []
    }

    # Planetary data with JPL Horizons IDs
    PLANETARY_IDS = [
        {"name": "Mercury", "horizons_id": "199", "color": "#A9A9A9"},
        {"name": "Venus", "horizons_id": "299", "color": "#FFD700"},
        {"name": "Earth", "horizons_id": "399", "color": "#00BFFF"},
        {"name": "Mars", "horizons_id": "499", "color": "#FF4500"},
        {"name": "Jupiter", "horizons_id": "599", "color": "#FFA500"}
    ]

    for planet in PLANETARY_IDS:
        # Fetch real data from Horizons API
        horizons_data = fetch_horizons_data(planet["horizons_id"], datetime.now())

        # Calculate orbital period from Kepler's third law (simplified)
        planet['period'] = math.sqrt(planet['semi_major_axis']**3) * 365.25

        # Calculate position
        x, y = calculate_elliptical_position(planet, days_since_epoch)

        # Combine with base data
        planet_data = {
            **planet,
            "position": {
                "x": x * AU,  # Convert AU to kilometers
                "y": y * AU
            },
            "orbital_radius": planet['semi_major_axis'] * AU,
            "eccentricity": planet['eccentricity'],
            "radius": planet['radius']
        }

        simulation_data['planets'].append(planet_data)

    return simulation_data

